<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Subcontractor registration</title><style>body{font:16px Arial;color:#172033;background:#f6f7fc;padding:24px}main{max-width:760px;margin:auto;background:white;padding:32px;border:1px solid #e2e5ef;border-radius:16px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}label{display:grid;gap:8px}input,select,button{font:inherit;padding:12px;border:1px solid #cdd3df;border-radius:8px;box-sizing:border-box;width:100%}button{background:#5141df;color:white;margin-top:24px}li{color:#b42318}@media(max-width:600px){.grid{grid-template-columns:1fr}main{padding:20px}body{padding:8px}}</style></head><body><main><h1>Subcontractor registration</h1>@if($expired??false)<h2>This link has expired</h2><p>Registration links are valid for 24 hours. Request a fresh link from our team to continue.</p><form method="POST" action="{{ url('/subcontractor-registration/'.$token.'/request-link') }}">@csrf<button>Request link</button></form>@elseif($requested??false)<p>Your request was sent to our team. They will share a fresh link with you.</p>@elseif($submitted??false)<p>Thank you. Your details have been submitted for review. Registration does not grant ERP access or guarantee a purchase order.</p>@else<p>Complete your company details. Our team will review them before adding you as a subcontractor.</p>@if($errors->any())<ul role="alert">@foreach($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul>@endif<form method="POST" action="{{ url('/subcontractor-registration/'.$token) }}">@csrf<input type="hidden" name="account_type" value="company"><div class="grid">@foreach(['name'=>'Company name','company_registry'=>'SSM / Registration number','tax_id'=>'Tax number','contact_person'=>'Contact person','email'=>'Email','phone'=>'Phone','mobile'=>'Mobile','website'=>'Website','street1'=>'Address line 1','street2'=>'Address line 2','city'=>'City / State / Country','zip'=>'Postcode'] as $key=>$label)<label>{{ $label }}{{ in_array($key,['name','company_registry','contact_person','email'])?' *':'' }}<input name="{{ $key }}" value="{{ old($key) }}" maxlength="255" type="{{ $key==='email'?'email':'text' }}" @required(in_array($key,['name','company_registry','contact_person','email']))></label>@endforeach</div><button>Submit for review</button></form>@endif</main></body></html>
